import { Badge, Icon } from 'antd'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'
import { format } from 'date-fns'
import { StyledAntdButton } from '../../../../../../components/uielements/customButton'
import ebUrls from '../../../../../../request/urls/employeeBenefit'
import styled from 'styled-components'

const StyledBadge = styled(Badge)`
  .ant-badge-multiple-words {
    background: ${(props) => props.bgColor};
    margin-right: 5;
    display: block;
  }
`

const handleDownloadClick = (request, fileId, status) => {
  request({ file_id: fileId, status })
}

export const fileUploadsColumns = (history, downloadFileUploads, cancelFileRequest, templateId, resetError, goToDetailPage) => ([

  {
    title: 'Action',
    width: 40,
    fixed: 'left',
    key: 1,
    render: (rowData) => (
      <PermissionCheckerV2 requiredPermission='ops.eb_view_claim_file_info'>
        <Icon
          type='eye'
          twoToneColor='#0180c8'
          theme='twoTone'
          style={{ cursor: 'pointer' }}
          onClick={() => goToDetailPage(rowData.id)}
        />
      </PermissionCheckerV2>
    )
  },
  {
    title: 'Name',
    dataIndex: 'name',
    key: 2
  },
  {
    title: 'Status',
    dataIndex: 'status',
    key: 3
  },
  {
    title: 'Row Status',
    dataIndex: 'filerows_status_count',
    render: (colData) => (
      <>
        <StyledBadge
          count={`Success: ${colData.success_rows}`}
          // style={{ backgroundColor: 'rgb(52, 199, 89)', display: 'block' }}
          bgColor='rgb(52, 199, 89)'
        />
        <StyledBadge count={`Failed: ${colData.failed_rows}`} bgColor='rgb(255, 59, 48)' />
        <StyledBadge count={`Duplicate: ${colData.duplicate_rows}`} bgColor='rgb(90, 200, 250)' />
      </>
    ),
    key: 4,
    width: 150
  },
  {
    title: 'Updated At',
    dataIndex: 'updated_at',
    render: date => format(date, 'DD MMMM YYYY'),
    key: 5
  },
  {
    title: 'Action',
    render: (rowData) => (
      <>
        <PermissionCheckerV2 requiredPermission='ops.eb_download_claim_file'>
          <StyledAntdButton
            type='customSuccess'
            className='display-block'
            shape='round' icon='download' size='small'
            onClick={() => {
              resetError(['DOWNLOAD_FILE_UPLOADS_ERROR'])
              handleDownloadClick(downloadFileUploads, rowData.id, 'SUCCESS')
            }}
          >
            Download Success
          </StyledAntdButton>
          <StyledAntdButton
            type='customDanger'
            className='display-block'
            shape='round' icon='download' size='small'
            onClick={() => {
              resetError(['DOWNLOAD_FILE_UPLOADS_ERROR'])
              handleDownloadClick(downloadFileUploads, rowData.id, 'FAILED')
            }}
          >
            Download failed
          </StyledAntdButton>
        </PermissionCheckerV2>
        <PermissionCheckerV2 requiredPermission='ops.eb_cancel_claim_file_processing'>
          {
            ['UPLOADED', 'INPROCESS'].includes(rowData.status) && (
              <StyledAntdButton
                type='customPrimary'
                shape='round'
                icon='close'
                size='small'
                onClick={() => {
                  resetError(['CANCEL_FILE_ERROR'])
                  cancelFileRequest({ file_id: rowData.id, url: ebUrls.cancelClaimFileProcessing })
                }}
              >
                Cancel
              </StyledAntdButton>
            )
          }
        </PermissionCheckerV2>
      </>
    ),
    key: 6
  }

])
