import { useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { Alert, Spin } from 'antd'
import React, { useCallback, useEffect } from 'react'
import FileUploads from '../../../components/FileUploadList'
import { useEbClaimConfig } from '../../../state/hooks'
import { fileUploadsColumns } from './utility'
import { useHistory } from 'react-router'

const ClaimStatusFileUploadList = () => {
  const { claimConfigRequest, claimConfigData } = useEbClaimConfig()
  const [{ CLAIM_CONFIG_LOADER }] = useLoaderContextValue()
  const [{ claimConfigStatus, CLAIM_CONFIG_ERROR }] = useErrorContextValue()
  const history = useHistory()

  const goToDetailPage = useCallback((fileId) => {
    history.push(`/employee-benefits/claim-management/file-uploads/${fileId}`)
  }, [history])

  useEffect(() => {
    claimConfigRequest()
  }, [claimConfigRequest])

  return (
    <Spin spinning={!!CLAIM_CONFIG_LOADER}>
      {CLAIM_CONFIG_ERROR && <div className='mb-5'><Alert type='error' message={claimConfigStatus} banner /></div>}
      {
        <FileUploads
          templateId={claimConfigData?.claim_bulk_status_update_template_id}
          fileUploadsColumns={fileUploadsColumns}
          goToDetailPage={goToDetailPage}
        />
      }
    </Spin>
  )
}
export default ClaimStatusFileUploadList
